CREATE TABLE `BusinessReview` (
  `id` CHAR(36) NOT NULL, `businessId` CHAR(36) NOT NULL, `userId` CHAR(36) NOT NULL, `rating` TINYINT UNSIGNED NOT NULL, `comment` TEXT NOT NULL, `status` ENUM('PUBLISHED','HIDDEN','REMOVED') NOT NULL DEFAULT 'PUBLISHED', `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `BusinessReview_businessId_userId_key` (`businessId`,`userId`), KEY `BusinessReview_businessId_status_createdAt_idx` (`businessId`,`status`,`createdAt`), KEY `BusinessReview_userId_createdAt_idx` (`userId`,`createdAt`), CONSTRAINT `BusinessReview_businessId_fkey` FOREIGN KEY (`businessId`) REFERENCES `Business` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `BusinessReview_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `BusinessReviewResponse` (`id` CHAR(36) NOT NULL, `reviewId` CHAR(36) NOT NULL, `ownerId` CHAR(36) NOT NULL, `body` TEXT NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `BusinessReviewResponse_reviewId_key` (`reviewId`), KEY `BusinessReviewResponse_ownerId_updatedAt_idx` (`ownerId`,`updatedAt`), CONSTRAINT `BusinessReviewResponse_reviewId_fkey` FOREIGN KEY (`reviewId`) REFERENCES `BusinessReview` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `BusinessReviewResponse_ownerId_fkey` FOREIGN KEY (`ownerId`) REFERENCES `User` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `BusinessReviewReport` (`id` CHAR(36) NOT NULL, `reviewId` CHAR(36) NOT NULL, `reporterId` CHAR(36) NOT NULL, `moderatorId` CHAR(36) NULL, `reason` ENUM('OFFENSIVE','SPAM','FALSE_INFORMATION','PERSONAL_DATA','OTHER') NOT NULL, `description` VARCHAR(1000) NULL, `status` ENUM('PENDING','UNDER_REVIEW','RESOLVED','REJECTED') NOT NULL DEFAULT 'PENDING', `decisionNote` VARCHAR(1000) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `BusinessReviewReport_reviewId_reporterId_status_key` (`reviewId`,`reporterId`,`status`), KEY `BusinessReviewReport_status_createdAt_idx` (`status`,`createdAt`), KEY `BusinessReviewReport_reviewId_status_idx` (`reviewId`,`status`), CONSTRAINT `BusinessReviewReport_reviewId_fkey` FOREIGN KEY (`reviewId`) REFERENCES `BusinessReview` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `BusinessReviewReport_reporterId_fkey` FOREIGN KEY (`reporterId`) REFERENCES `User` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `BusinessReviewReport_moderatorId_fkey` FOREIGN KEY (`moderatorId`) REFERENCES `User` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
